BEGIN READ ONLY;
DO $preflight$ DECLARE t text; BEGIN
 IF to_regnamespace('pharmflow_auth_private') IS NOT NULL THEN RAISE EXCEPTION 'Authorization release already partially or fully present; reconcile before proceeding'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles r,unnest(coalesce(r.rolconfig,ARRAY[]::text[])) c WHERE rolname='authenticator' AND c LIKE 'pgrst.db_pre_request=%') THEN RAISE EXCEPTION 'Existing request hook needs explicit composition';END IF;
 IF (SELECT count(*) FROM public.pharmacies WHERE code='HHP084')<>1 THEN RAISE EXCEPTION 'HHP084 UUID bootstrap ambiguous';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.pharmacies p JOIN public.pharmacy_members m ON m.pharmacy_id=p.id WHERE p.code='HHP084' AND p.active AND m.active AND m.role='admin') THEN RAISE EXCEPTION 'HHP084 active admin membership missing';END IF;
 FOREACH t IN ARRAY ARRAY['sessions','session_items','transactions'] LOOP
  IF has_table_privilege('anon','public.'||t,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('authenticated','public.'||t,'SELECT,INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'Legacy table API exposure: %',t;END IF;
 END LOOP;
END $preflight$;
